import { readFileSync, writeFileSync } from "node:fs";
import { isAbsolute, join, relative } from "node:path";
import { validateInstance, withDefaults } from "./instance.js";
import { parseJsonc } from "./jsonc.js";

// service/control/wrangler.jsonc is a template without any owner's values. A
// deployment uses wrangler.instance.jsonc, rendered from the template and the
// instance file; the end-to-end tests render a local config from the same
// template (Agent Note 2026-10-11-distribution-to-other-owners).

export const GENERATED_HEADER = [
  "// Generated by `npm run yolo -- config render` from wrangler.jsonc and the",
  "// instance file; do not edit. Deploys use this file; wrangler.jsonc is the",
  "// template every instance shares.",
].join("\n");

export function readTemplate(path) {
  return parseJsonc(readFileSync(path, "utf8"));
}

export class InstanceConfigError extends Error {
  constructor(problems) {
    super(problems.map((problem) => `${problem.field || "instance"}: ${problem.message}`).join("; "));
    this.name = "InstanceConfigError";
    this.problems = problems;
  }
}

const withBinding = (list, binding, patch) => (list ?? []).map((entry) => (entry.binding === binding ? { ...entry, ...patch } : entry));

// The template plus one instance's values: the route, PUBLIC_ORIGIN, the
// node's address, the D1 and KV ids, and the VPC service.
export function renderInstanceConfig(template, raw) {
  const problems = validateInstance(raw, { deploy: true });
  if (problems.length) throw new InstanceConfigError(problems);
  const instance = withDefaults(raw);
  const config = structuredClone(template);
  config.name = instance.worker;
  if (instance.accountId) config.account_id = instance.accountId;
  config.routes = [{ pattern: instance.domain, custom_domain: true }];
  config.vars = {
    ...config.vars,
    PUBLIC_ORIGIN: instance.publicOrigin,
    NODE_TRANSPORT: instance.transport,
    NODE_ORIGIN: `http://127.0.0.1:${instance.node.port}`,
    NODE_PUBLIC_ORIGIN: instance.transport === "tunnel" ? instance.nodePublicOrigin : "",
  };
  config.d1_databases = withBinding(config.d1_databases, "DB", { database_name: instance.d1.name, database_id: instance.d1.id });
  config.kv_namespaces = withBinding(config.kv_namespaces, "OAUTH_KV", { id: instance.kv.id });
  if (instance.transport === "vpc") config.vpc_services = [{ binding: "NODE", service_id: instance.vpc.serviceId }];
  else delete config.vpc_services;
  return config;
}

export function serializeGenerated(config) {
  return `${GENERATED_HEADER}\n${JSON.stringify(config, null, 2)}\n`;
}

// Writes only when the content changes; returns whether it did.
export function writeGenerated(path, config) {
  const text = serializeGenerated(config);
  let current = null;
  try {
    current = readFileSync(path, "utf8");
  } catch {
    // Not rendered yet.
  }
  if (current === text) return false;
  writeFileSync(path, text);
  return true;
}

// A config that never reaches Cloudflare: no route, no VPC binding, no cron,
// placeholder D1 and KV ids, and absolute paths so it can live anywhere.
// `node` replaces a leading `node` in the build command (the tests run
// wrangler with their own Node binary).
export function renderLocalConfig(template, { controlDir, name, migrationsDir, d1Id, kvId, node }) {
  const config = structuredClone(template);
  const absolute = (path) => (isAbsolute(path) ? path : join(controlDir, path));
  delete config.$schema;
  delete config.routes;
  delete config.vpc_services;
  delete config.triggers;
  delete config.account_id;
  config.name = name;
  config.main = absolute(config.main);
  if (config.assets?.directory) config.assets = { ...config.assets, directory: absolute(config.assets.directory) };
  if (config.build?.command) {
    const command = node ? config.build.command.replace(/(^|&&\s*)node /g, `$1"${node}" `) : config.build.command;
    config.build = { ...config.build, command, cwd: absolute(config.build.cwd ?? ".") };
  }
  config.d1_databases = withBinding(config.d1_databases, "DB", {
    database_id: d1Id,
    migrations_dir: migrationsDir ?? absolute(config.d1_databases?.find((entry) => entry.binding === "DB")?.migrations_dir ?? "migrations"),
  });
  config.kv_namespaces = withBinding(config.kv_namespaces, "OAUTH_KV", { id: kvId });
  return config;
}

// How the generated file differs from what the template and instance give
// now: null when current, else a short reason.
export function generatedDrift(path, template, raw) {
  let current;
  try {
    current = readFileSync(path, "utf8");
  } catch {
    return `${relative(process.cwd(), path) || path} has not been rendered`;
  }
  return current === serializeGenerated(renderInstanceConfig(template, raw)) ? null : "it is older than wrangler.jsonc or the instance file";
}
